actor User {}
actor ServiceAccount {}
resource Repo { roles = ["admin","maintainer","viewer"] }
resource Org {}

has_role(actor: User, role, repo: Repo) if repo.has_role(actor.id, role);

allow(user: User, "read", repo: Repo) if has_role(user, "viewer", repo);
allow(user: User, "write", repo: Repo) if has_role(user, "maintainer", repo);
allow(user: User, "admin", repo: Repo) if has_role(user, "admin", repo);

allow(sa: ServiceAccount, "read", repo: Repo) if repo.org_id = sa.org_id;

actor User {}
actor ServiceAccount {}
resource Repo {}
resource Org {}
resource Issue { repo_id: String }

has_role(user: User, role, repo: Repo) if repo.has_role(user.id, role);

allow(user: User, "read", repo: Repo) if has_role(user, "viewer", repo);
allow(user: User, "write", repo: Repo) if has_role(user, "maintainer", repo);
allow(user: User, "admin", repo: Repo) if has_role(user, "admin", repo);

allow(user: User, "read", issue: Issue) if has_role(user, "viewer", Repo{id: issue.repo_id});
allow(user: User, "triage", issue: Issue) if has_role(user, "maintainer", Repo{id: issue.repo_id});

allow(sa: ServiceAccount, "read", repo: Repo) if repo.org_id = sa.org_id;

actor User {}
resource Dataset { owner_id: String, org_id: String }
resource Notebook { dataset_id: String, org_id: String }

allow(user: User, "read", ds: Dataset) if ds.org_id = user.org_id;
allow(user: User, "write", ds: Dataset) if ds.owner_id = user.id;
allow(user: User, "share", ds: Dataset) if ds.owner_id = user.id;

allow(user: User, "read", nb: Notebook) if allow(user, "read", Dataset{id: nb.dataset_id});

actor User {}
actor ApiClient {}
resource Dataset { owner_id: String, org_id: String, visibility: String }
resource Notebook { dataset_id: String, org_id: String }

allow(user: User, "read", ds: Dataset) if ds.visibility = "public";
allow(user: User, "read", ds: Dataset) if ds.org_id = user.org_id;
allow(user: User, "write", ds: Dataset) if ds.owner_id = user.id;
allow(user: User, "share", ds: Dataset) if ds.owner_id = user.id;

allow(client: ApiClient, "read", ds: Dataset) if ds.org_id = client.org_id;

allow(user: User, "read", nb: Notebook) if allow(user, "read", Dataset{id: nb.dataset_id});

actor User {}
resource Project { org_id: String }
resource Ticket { project_id: String }

is_member(user: User, project: Project) if project.org_id = user.org_id;

allow(user: User, "read", project: Project) if is_member(user, project);
allow(user: User, "read", ticket: Ticket) if is_member(user, Project{id: ticket.project_id});
allow(user: User, "comment", ticket: Ticket) if is_member(user, Project{id: ticket.project_id});

actor User {}
resource Project { org_id: String }
resource Ticket { project_id: String }

is_member(user: User, project: Project) if project.org_id = user.org_id;

allow(user: User, "read", project: Project) if is_member(user, project);
allow(user: User, "read", ticket: Ticket) if is_member(user, Project { id: ticket.project_id });
allow(user: User, "comment", ticket: Ticket) if is_member(user, Project { id: ticket.project_id });
allow(user: User, "close", ticket: Ticket) if user.role = "support" and is_member(user, Project { id: ticket.project_id });

actor User {}
resource Project { org_id: String }
resource Ticket { project_id: String, requester_id: String }

is_member(user: User, project: Project) if project.org_id = user.org_id;

allow(user: User, "read", ticket: Ticket) if is_member(user, Project { id: ticket.project_id });
allow(user: User, "comment", ticket: Ticket) if is_member(user, Project { id: ticket.project_id });
allow(user: User, "close", ticket: Ticket) if user.role = "support" and is_member(user, Project { id: ticket.project_id });
allow(user: User, "view_private", ticket: Ticket) if ticket.requester_id = user.id;

actor User {}
resource Account { owner_id: String }
resource Invoice { account_id: String }

allow(user: User, "read", acct: Account) if acct.owner_id = user.id;
allow(user: User, "update", acct: Account) if acct.owner_id = user.id;
allow(user: User, "read", inv: Invoice) if allow(user, "read", Account { id: inv.account_id });

actor User {}
actor Admin {}
resource Account { owner_id: String, org_id: String }
resource Invoice { account_id: String, status: String }

allow(user: User, "read", acct: Account) if acct.owner_id = user.id;
allow(user: User, "update", acct: Account) if acct.owner_id = user.id;

allow(admin: Admin, "read", acct: Account) if acct.org_id = admin.org_id;
allow(admin: Admin, "refund", inv: Invoice) if inv.status = "paid" and allow(admin, "read", Account { id: inv.account_id });

allow(user: User, "read", inv: Invoice) if allow(user, "read", Account { id: inv.account_id });

actor User {}
resource Doc { owner_id: String, team_id: String }

allow(user: User, "read", doc: Doc) if doc.team_id in user.team_ids;
allow(user: User, "edit", doc: Doc) if doc.owner_id = user.id;
allow(user: User, "comment", doc: Doc) if doc.team_id in user.team_ids;

actor User {}
resource Environment { org_id: String }
resource Secret { env_id: String }

allow(user: User, "read", env: Environment) if env.org_id = user.org_id;
allow(user: User, "deploy", env: Environment) if user.role = "release" and env.org_id = user.org_id;
allow(user: User, "read", sec: Secret) if allow(user, "read", Environment { id: sec.env_id });

actor User {}
resource Folder { org_id: String }
resource File { folder_id: String }

allow(user: User, "read", folder: Folder) if folder.org_id = user.org_id;
allow(user: User, "create", folder: Folder) if user.role in ["editor","admin"] and folder.org_id = user.org_id;
allow(user: User, "read", file: File) if allow(user, "read", Folder { id: file.folder_id });

actor User {}
resource Folder { org_id: String }
resource File { folder_id: String, owner_id: String }

allow(user: User, "read", folder: Folder) if folder.org_id = user.org_id;
allow(user: User, "create", folder: Folder) if user.role in ["editor","admin"] and folder.org_id = user.org_id;

allow(user: User, "read", file: File) if allow(user, "read", Folder { id: file.folder_id });
allow(user: User, "delete", file: File) if user.role = "admin" or file.owner_id = user.id;

actor User {}
resource Service { org_id: String }
resource Incident { service_id: String }

allow(user: User, "read", svc: Service) if svc.org_id = user.org_id;
allow(user: User, "page", svc: Service) if user.oncall = true and svc.org_id = user.org_id;

allow(user: User, "read", inc: Incident) if allow(user, "read", Service { id: inc.service_id });
allow(user: User, "ack", inc: Incident) if user.oncall = true and allow(user, "read", Service { id: inc.service_id });

actor User {}
resource Service { org_id: String }
resource Incident { service_id: String }

allow(user: User, "read", svc: Service) if svc.org_id = user.org_id;
allow(user: User, "page", svc: Service) if user.role = "oncall" and svc.org_id = user.org_id;

allow(user: User, "read", inc: Incident) if allow(user, "read", Service { id: inc.service_id });
allow(user: User, "ack", inc: Incident) if user.role = "oncall" and allow(user, "read", Service { id: inc.service_id });

actor User {}
resource Workspace { org_id: String }
resource Report { workspace_id: String, classification: String }

allow(user: User, "read", ws: Workspace) if ws.org_id = user.org_id;
allow(user: User, "export", rpt: Report) if user.role = "analyst" and rpt.classification != "restricted";
allow(user: User, "read", rpt: Report) if allow(user, "read", Workspace { id: rpt.workspace_id });

actor User {}
actor MachineUser {}
resource Bucket { org_id: String }
resource Object { bucket_id: String }

allow(user: User, "read", b: Bucket) if b.org_id = user.org_id;
allow(user: User, "write", b: Bucket) if user.role = "storage_admin" and b.org_id = user.org_id;

allow(mu: MachineUser, "read", b: Bucket) if b.org_id = mu.org_id;

allow(user: User, "read", o: Object) if allow(user, "read", Bucket { id: o.bucket_id });

actor User {}
resource Team { org_id: String }
resource Member { team_id: String, user_id: String }

allow(user: User, "read", team: Team) if team.org_id = user.org_id;
allow(user: User, "manage", team: Team) if user.role = "org_admin" and team.org_id = user.org_id;

allow(user: User, "read", m: Member) if allow(user, "read", Team { id: m.team_id });
